contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _value) public {
        uint256 bal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(_value <= bal);
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.burn(_value); if (__ESBMC_reverted()) return;
        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(afterSupply == beforeSupply - _value);
    }

    receive() external payable {}
}

